import pandas as pd

def products_price(products: pd.DataFrame) -> pd.DataFrame:
    pivot = products.pivot(index="product_id", columns="store", values="price").reset_index()
    for s in ["store1", "store2", "store3"]:
        if s not in pivot.columns:
            pivot[s] = None
    return pivot[["product_id", "store1", "store2", "store3"]]
